-- The roaster kind a profile was written for (docs/profiles.md, "Roaster kinds"): one
-- of the setup kinds (docs/roaster-setup.md), or none. The profile library
-- lists the selected roaster's kind first and marks the others; nothing is hidden.
ALTER TABLE roast_profiles ADD COLUMN roaster_kind TEXT;
-- fluid_bed_electric | drum_electric | drum_gas | logger | other

-- The fluid-bed seeds (migrations 014, 015, 021) were written for the owner's fluid bed.
UPDATE roast_profiles SET roaster_kind = 'fluid_bed_electric' WHERE id LIKE 'fluidbed-%';

-- Two drum seeds, generated by: python3 scripts/gen_drum_profiles.py
DELETE FROM profile_points WHERE profile_id = 'drum-light-filter';
DELETE FROM profile_events WHERE profile_id = 'drum-light-filter';

DELETE FROM profile_points WHERE profile_id = 'drum-medium-omni';
DELETE FROM profile_events WHERE profile_id = 'drum-medium-omni';

