INSERT INTO roast_profiles (id, name, description, is_public, target_total_time, target_first_crack, target_end_temp, charge_temp, roast_level, roast_purpose, roaster_kind) VALUES ('drum-light-filter', 'Drum — Light (filter)', 'Light filter roast for a small drum, preheated. Charge ~200 °C, turning point ~1:25 at ~97 °C, dry end ~4:15 at 150 °C, FC ~8:15 at ~196 °C, drop 9:45 at 205 °C (development 1:30, ~15 %). Burner 65 % stepping to 55 % before first crack; air 40 % rising to 60 %. Written from published drum roasting practice (Rao, Green Coffee Collective) and checked on the simulated drum.', 1, 585, 495, 205.0, 200.0, 'light', 'filter', 'drum_gas') ON CONFLICT(id) DO UPDATE SET name = excluded.name, description = excluded.description, target_total_time = excluded.target_total_time, target_first_crack = excluded.target_first_crack, target_end_temp = excluded.target_end_temp, charge_temp = excluded.charge_temp, roast_level = excluded.roast_level, roast_purpose = excluded.roast_purpose, roaster_kind = excluded.roaster_kind;
