INSERT INTO roast_profiles (id, name, description, is_public, target_total_time, target_first_crack, target_end_temp, charge_temp, roast_level, roast_purpose, roaster_kind) VALUES ('drum-medium-omni', 'Drum — Medium omni', 'Medium roast for a small drum that works as filter and espresso, preheated. Charge ~205 °C, turning point ~1:30 at ~100 °C, dry end ~4:35 at 150 °C, FC ~8:45 at ~196 °C, drop 11:00 at 211 °C (development 2:15, ~20 %). Burner 65 % stepping to 60 % at 5:00; air 30 % rising to 50 %. Written from published drum roasting practice (Rao, Green Coffee Collective) and checked on the simulated drum.', 1, 660, 525, 211.0, 205.0, 'medium', 'omni', 'drum_gas') ON CONFLICT(id) DO UPDATE SET name = excluded.name, description = excluded.description, target_total_time = excluded.target_total_time, target_first_crack = excluded.target_first_crack, target_end_temp = excluded.target_end_temp, charge_temp = excluded.charge_temp, roast_level = excluded.roast_level, roast_purpose = excluded.roast_purpose, roaster_kind = excluded.roaster_kind;
